def parse_demos(text):
  # Parse each pair sections (shape title), read H lines after heading, row ints
  out=[]
  lines=text.splitlines(); i=0
  while i<len(lines):
   m=re.match(r'Demo pair (\d+) (input|output) \((\d+)x(\d+)\):',lines[i])
   if m:
    num,typ,h,w=int(m[1]),m[2],int(m[3]),int(m[4]); rows=[]
    for ln in lines[i+1:i+1+h]:
     vals=list(map(int,ln.split()))
     if len(vals)!=w: print('bad row',num,typ,len(vals),w)
     rows.append(vals)
    out.append((num,typ,rows)); i+=h+1
   else:i+=1
  return out
